prompts.user:
/ [셋업] POS별 문항 풀에서 랜덤 인덱스(*_IDX) 추출
@SET(N_IDX, "@INDEX("@PRM_N@", "@PRM_N[.]@")@", SELF)@
@SET(V_IDX, "@INDEX("@PRM_V@", "@PRM_V[.]@")@", SELF)@
@SET(ADJ_IDX, "@INDEX("@PRM_ADJ@", "@PRM_ADJ[.]@")@", SELF)@
@SET(OTH_IDX, "@INDEX("@PRM_OTH@", "@PRM_OTH[.]@")@", SELF)@

// [셋업] 추출한 문항·정답(·보기)을 JSON_test_config에 기록
@UPJ(JSON_test_config.Noun[@R_i@].problem, "@EVAL(@R_i@)@. 단어 <b>@PRM_N[@N_IDX@]@</b>에 해당하는 단어를 고르시오.")@
@UPJ(JSON_test_config.Noun[@R_i@].answer, "@ANS_N[@N_IDX@]@")@
@UPJ(JSON_test_config.Noun[@R_i@].distractor, "@D("@ANS_N[@N_IDX@]@", "", "@ANS_N@", 4)@")@

@UPJ(JSON_test_config.Verb[@R_i@].problem, "@EVAL(@R_i@)@. 단어 <b>@PRM_V[@V_IDX@]@</b>에 해당하는 단어를 고르시오.")@
@UPJ(JSON_test_config.Verb[@R_i@].answer, "@ANS_V[@V_IDX@]@")@
@UPJ(JSON_test_config.Verb[@R_i@].distractor, "@D("@ANS_V[@V_IDX@]@", "", "@ANS_V@", 4)@")@

@UPJ(JSON_test_config.Adjective[@R_i@].problem, "@EVAL(@R_i@)@. 단어 <b>@PRM_ADJ[@ADJ_IDX@]@</b>에 해당하는 단어를 고르시오.")@
@UPJ(JSON_test_config.Adjective[@R_i@].answer, "@ANS_ADJ[@ADJ_IDX@]@")@

@UPJ(JSON_test_config.Adjective[@R_i@].distractor, "@D("@ANS_ADJ[@ADJ_IDX@]@", "", "@ANS_ADJ@", 4)@")@

@UPJ(JSON_test_config.others[@R_i@].problem, "@EVAL(@R_i@)@. 단어 <b>@PRM_OTH[@OTH_IDX@]@</b>에 해당하는 단어를 고르시오.")@
@UPJ(JSON_test_config.others[@R_i@].answer, "@ANS_OTH[@OTH_IDX@]@")@
@UPJ(JSON_test_config.others[@R_i@].distractor, "@D("@ANS_OTH[@OTH_IDX@]@", "", "@ANS_OTH@", 4)@")@

// [채점] 학생 응답 정오 판정 후 점수·correctness 기록 (EXACT: 정확 일치)

1. Noun
T/F boolean: @MAP("@RADIO(P_N@R_i@)@", "@JSON_test_config.Noun[@R_i@].answer@", "1|0",EXACT)@

Current Score: @JSON_test_config.Result[1].Noun@

Enumerated: @EVAL("@JSON_test_config.Result[1].Noun@ + @MAP("@RADIO(P_N@R_i@)@", "@JSON_test_config.Noun[@R_i@].answer@", "1|0",EXACT)@")@

update:
@UPJ(JSON_test_config.Result[1].Noun, @EVAL("@JSON_test_config.Result[1].Noun@ + @MAP("@RADIO(P_N@R_i@)@", "@JSON_test_config.Noun[@R_i@].answer@", "1|0",EXACT)@")@)@
@UPJ(JSON_test_config.Noun[@R_i@].Student_answer, "@RADIO(P_N@R_i@)@")@
@UPJ(JSON_test_config.Noun[@R_i@].correctness, @MAP("@RADIO(P_N@R_i@)@", "@JSON_test_config.Noun[@R_i@].answer@", "1|0",EXACT)@)@

